CREATE TABLE mail_row(id TEXT PRIMARY KEY,run_id TEXT NOT NULL,source_kind TEXT NOT NULL,ordinal INTEGER NOT NULL,native_id TEXT NOT NULL,source_path TEXT NOT NULL,pointer TEXT NOT NULL,raw_json TEXT NOT NULL,raw_sha256 TEXT NOT NULL,UNIQUE(source_path,ordinal)) WITHOUT ROWID;
CREATE TABLE mail_slot(id TEXT PRIMARY KEY,row_id TEXT NOT NULL REFERENCES mail_row(id),owner_field TEXT NOT NULL,locale TEXT NOT NULL,raw_locator TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('resolved_main','resolved_medium','missing','ambiguous','mapping_unresolved')),candidate_count INTEGER NOT NULL,UNIQUE(row_id,owner_field,locale)) WITHOUT ROWID;
CREATE TABLE mail_text(id TEXT PRIMARY KEY,slot_id TEXT NOT NULL REFERENCES mail_slot(id),source_path TEXT NOT NULL,pair_ordinal INTEGER NOT NULL,pointer TEXT NOT NULL,raw_text TEXT NOT NULL,raw_text_sha256 TEXT NOT NULL,UNIQUE(slot_id,source_path,pair_ordinal)) WITHOUT ROWID;
CREATE TABLE mail_relation(id TEXT PRIMARY KEY,row_id TEXT NOT NULL REFERENCES mail_row(id),kind TEXT NOT NULL,source_pointer TEXT NOT NULL,raw_value TEXT NOT NULL,candidate_namespace TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('resolved_unique','missing','ambiguous','mapping_unresolved')),candidate_count INTEGER NOT NULL,search_complete INTEGER NOT NULL CHECK(search_complete IN (0,1)),UNIQUE(row_id,kind,source_pointer)) WITHOUT ROWID;
CREATE TABLE mail_candidate(id TEXT PRIMARY KEY,relation_id TEXT NOT NULL REFERENCES mail_relation(id),target_row_id TEXT NOT NULL REFERENCES mail_row(id),target_source_path TEXT NOT NULL,target_ordinal INTEGER NOT NULL,target_pointer TEXT NOT NULL,target_raw_sha256 TEXT NOT NULL,UNIQUE(relation_id,target_source_path,target_ordinal)) WITHOUT ROWID;
CREATE TABLE mail_release(id INTEGER PRIMARY KEY CHECK(id=1),manifest_json TEXT NOT NULL) WITHOUT ROWID;
CREATE INDEX mail_slot_parent ON mail_slot(row_id);
CREATE INDEX mail_text_slot ON mail_text(slot_id);
CREATE INDEX mail_text_value ON mail_text(raw_text);
CREATE INDEX mail_relation_parent ON mail_relation(row_id);
CREATE INDEX mail_candidate_relation ON mail_candidate(relation_id);
CREATE TRIGGER mail_row_i BEFORE INSERT ON mail_row WHEN EXISTS(SELECT 1 FROM mail_release) BEGIN SELECT RAISE(ABORT,'immutable sealed Mail 7.1');END;
CREATE TRIGGER mail_slot_i BEFORE INSERT ON mail_slot WHEN EXISTS(SELECT 1 FROM mail_release) BEGIN SELECT RAISE(ABORT,'immutable sealed Mail 7.1');END;
CREATE TRIGGER mail_text_i BEFORE INSERT ON mail_text WHEN EXISTS(SELECT 1 FROM mail_release) BEGIN SELECT RAISE(ABORT,'immutable sealed Mail 7.1');END;
CREATE TRIGGER mail_relation_i BEFORE INSERT ON mail_relation WHEN EXISTS(SELECT 1 FROM mail_release) BEGIN SELECT RAISE(ABORT,'immutable sealed Mail 7.1');END;
CREATE TRIGGER mail_candidate_i BEFORE INSERT ON mail_candidate WHEN EXISTS(SELECT 1 FROM mail_release) BEGIN SELECT RAISE(ABORT,'immutable sealed Mail 7.1');END;
CREATE TRIGGER mail_release_i BEFORE INSERT ON mail_release WHEN EXISTS(SELECT 1 FROM mail_release) BEGIN SELECT RAISE(ABORT,'immutable sealed Mail 7.1');END;
CREATE TRIGGER mail_row_u BEFORE UPDATE ON mail_row BEGIN SELECT RAISE(ABORT,'immutable sealed Mail 7.1');END;
CREATE TRIGGER mail_row_d BEFORE DELETE ON mail_row BEGIN SELECT RAISE(ABORT,'immutable sealed Mail 7.1');END;
CREATE TRIGGER mail_slot_u BEFORE UPDATE ON mail_slot BEGIN SELECT RAISE(ABORT,'immutable sealed Mail 7.1');END;
CREATE TRIGGER mail_slot_d BEFORE DELETE ON mail_slot BEGIN SELECT RAISE(ABORT,'immutable sealed Mail 7.1');END;
CREATE TRIGGER mail_text_u BEFORE UPDATE ON mail_text BEGIN SELECT RAISE(ABORT,'immutable sealed Mail 7.1');END;
CREATE TRIGGER mail_text_d BEFORE DELETE ON mail_text BEGIN SELECT RAISE(ABORT,'immutable sealed Mail 7.1');END;
CREATE TRIGGER mail_relation_u BEFORE UPDATE ON mail_relation BEGIN SELECT RAISE(ABORT,'immutable sealed Mail 7.1');END;
CREATE TRIGGER mail_relation_d BEFORE DELETE ON mail_relation BEGIN SELECT RAISE(ABORT,'immutable sealed Mail 7.1');END;
CREATE TRIGGER mail_candidate_u BEFORE UPDATE ON mail_candidate BEGIN SELECT RAISE(ABORT,'immutable sealed Mail 7.1');END;
CREATE TRIGGER mail_candidate_d BEFORE DELETE ON mail_candidate BEGIN SELECT RAISE(ABORT,'immutable sealed Mail 7.1');END;
CREATE TRIGGER mail_release_u BEFORE UPDATE ON mail_release BEGIN SELECT RAISE(ABORT,'immutable sealed Mail 7.1');END;
CREATE TRIGGER mail_release_d BEFORE DELETE ON mail_release BEGIN SELECT RAISE(ABORT,'immutable sealed Mail 7.1');END;
